  Plus, Star, User, ShoppingBag, Save, Trash2, Trophy, MapPin, Phone, MessageSquare, Package, UserCircle, X, Sparkles, Camera, ClipboardList, SkipForward, Calendar, Gift, Users, Heart, ArrowLeft, ChevronRight, ShoppingCart, CreditCard, Search, Filter
} from 'lucide-react';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [splashFade, setSplashFade] = useState(false);
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [toast, setToast] = useState<{message: string, type: ToastType} | null>(null);
