      if (!supabase) return;
      try {
        const { data, error } = await supabase
          .from('menu_items')
          .select('*')
          .eq('is_available', true);

        if (data && data.length > 0) {
          const mappedItems: MenuItem[] = data.map((item: any) => ({
            id: item.id,
            name: item.name,
            description: item.description,
            price: Number(item.price),
            image: item.image,
            category: item.category as MenuCategory,
            rating: Number(item.rating),
            isAvailable: item.is_available,
            isPlatDuJour: item.is_plat_du_jour,
            isSpicy: item.is_spicy,
            isVegetarian: item.is_vegetarian,
            isSpécialitéMaison: item.is_specialite_maison,
            isPromo: item.is_promo,
            includes: item.includes,
            minPeople: item.min_people
          }));
          setItems(mappedItems);
        }
      } catch (err) {
        console.error("Erreur chargement menu Supabase:", err);
      }
    };
    fetchMenu();
