import DeliveryEstimator from './components/DeliveryEstimator';
import ItemDetailsModal from './components/ItemDetailsModal'; 
import TraiteurView from './components/TraiteurView';
import UpsellModal from './components/UpsellModal';
import Toast, { ToastType } from './components/Toast';
import { KhadyLogo } from './components/KhadyLogo';
import { playSound } from './utils/audio';
import { supabase } from './lib/supabase';
import { Page, MenuItem, CartItem, Review, Order, OrderStatus, PaymentMethod, MenuCategory } from './types';
import { MENU_ITEMS, REVIEWS as INITIAL_REVIEWS, RESTAURANT_INFO, DISTRICTS, LOGO_VIDEO_URL, BILLO_INFO } from './constants';
import { 
  Plus, Star, User, ShoppingBag, Save, Trash2, Trophy, MapPin, Phone, MessageSquare, Package, UserCircle, X, Sparkles, Camera, ClipboardList, SkipForward, Calendar, Gift, Users, Heart, ArrowLeft, ChevronRight, ShoppingCart, CreditCard, Search, Filter, Info, Lock
} from 'lucide-react';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [splashFade, setSplashFade] = useState(false);
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [toast, setToast] = useState<{message: string, type: ToastType} | null>(null);

  // États de données
  const [cart, setCart] = useState<CartItem[]>(() => JSON.parse(localStorage.getItem('khadys_cart') || '[]'));
  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [reviews, setReviews] = useState<Review[]>(INITIAL_REVIEWS);
  const [profile, setProfile] = useState(() => JSON.parse(localStorage.getItem('khadys_profile') || JSON.stringify({ name: '', phone: '', email: '', address: '', district: '', photo: null })));

  const [selectedItemForDetails, setSelectedItemForDetails] = useState<MenuItem | null>(null);
  const [activeCategory, setActiveCategory] = useState<MenuCategory | 'Tout'>('Tout');
  const [showUpsell, setShowUpsell] = useState(false);

  // Synchronisation avec Supabase (si disponible)
  useEffect(() => {
    const fetchData = async () => {
      if (!supabase) return;

      try {
        // Fetch Menu
        const { data: menuData } = await supabase.from('menu_items').select('*').eq('is_available', true);
        if (menuData && menuData.length > 0) {
          const mappedItems: MenuItem[] = menuData.map((item: any) => ({
            id: item.id,
            name: item.name,
            description: item.description,
            price: Number(item.price),
            image: item.image,
            category: item.category as MenuCategory,
            rating: Number(item.rating),
            isAvailable: item.is_available,
            isPlatDuJour: item.is_plat_du_jour,
            isSpicy: item.is_spicy,
            isVegetarian: item.is_vegetarian,
            isSpécialitéMaison: item.is_specialite_maison,
            isPromo: item.is_promo,
            includes: item.includes,
            minPeople: item.min_people
          }));
          setItems(mappedItems);
        }

        // Fetch Reviews
        const { data: reviewData } = await supabase.from('reviews').select('*').order('created_at', { ascending: false });
        if (reviewData && reviewData.length > 0) {
          setReviews(reviewData.map((r: any) => ({
            id: r.id,
            name: r.name,
            comment: r.comment,
            rating: r.rating,
            image: r.image || 'https://images.unsplash.com/photo-1511367461989-f85a21fda167?w=100',
            date: new Date(r.created_at).toLocaleDateString(),
            adminReply: r.admin_reply
          })));
        }
      } catch (err) {
        console.error("Erreur chargement Supabase:", err);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    localStorage.setItem('khadys_cart', JSON.stringify(cart));
  }, [cart]);

  const closeSplash = () => {
    setSplashFade(true);
    setTimeout(() => setShowSplash(false), 800);
  };

  const showNotification = (message: string, type: ToastType = 'success') => setToast({ message, type });

  const filteredItems = useMemo(() => {
    let baseItems = items;
    if (currentPage === Page.BOX) return baseItems.filter(i => i.category === 'Box');
    if (currentPage === Page.PACKS) return baseItems.filter(i => i.category === 'Pack');
    if (activeCategory !== 'Tout') return baseItems.filter(i => i.category === activeCategory);
    return baseItems.filter(i => i.category !== 'Box' && i.category !== 'Pack');
  }, [items, activeCategory, currentPage]);

  const handleAddToCart = (item: MenuItem, quantity: number, instructions: string) => {
    const existing = cart.find(c => c.id === item.id);
    if (existing) {
      setCart(cart.map(c => c.id === item.id ? { ...c, quantity: c.quantity + quantity, instructions } : c));
    } else {
      setCart([...cart, { ...item, quantity, instructions }]);
    }
    playSound('pop');
    showNotification(`${item.name} ajouté !`);
  };

  const removeFromCart = (id: string) => {
    setCart(cart.filter(item => item.id !== id));
    playSound('pop');
  };

  const renderContent = () => {
    if (currentPage === Page.ADMIN) {
      return (
        <AdminDashboard 
          items={items} setItems={setItems} 
          orders={orders} setOrders={setOrders} 
          reviews={reviews} setReviews={setReviews} 
          onExit={() => setCurrentPage(Page.HOME)} 
          adminPhoto={null} setAdminPhoto={() => {}} 
          adminPhone="" setAdminPhone={() => {}} 
          loyaltyConfig={{}} setLoyaltyConfig={() => {}}
        />
      );
    }

    switch(currentPage) {
      case Page.HOME:
        return (
          <div className="pb-32 animate-fade-in w-full">
            <div className="flex justify-between items-center py-6 px-6 bg-brand-cream/80 backdrop-blur-md sticky top-0 z-40">
              <KhadyLogo />
              <button onClick={() => setCurrentPage(Page.COMPTE)} className="w-12 h-12 rounded-2xl border-2 border-brand-brown/10 overflow-hidden shadow-lg bg-white p-0.5">
                {profile.photo ? <img src={profile.photo} className="w-full h-full object-cover rounded-[0.8rem]" /> : <div className="w-full h-full flex items-center justify-center bg-brand-brown/5"><User size={20} className="text-brand-brown" /></div>}
              </button>
            </div>

            <div className="mt-8 px-6">
                <div className="relative w-full aspect-[16/10] rounded-[3.5rem] overflow-hidden shadow-2xl border-4 border-white group cursor-pointer" onClick={() => setSelectedItemForDetails(items.find(i => i.isPlatDuJour) || items[0])}>
                   <img src={items.find(i => i.isPlatDuJour)?.image || items[0].image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                   <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent"></div>
                   <div className="absolute bottom-8 left-8 text-white">
                      <span className="bg-brand-orange text-[9px] font-black uppercase px-3 py-1 rounded-full mb-3 inline-block animate-bounce shadow-lg">Plat du Jour 🥘</span>
                      <h3 className="text-2xl font-black uppercase italic tracking-tighter mb-1">{items.find(i => i.isPlatDuJour)?.name || "Menu Spécial"}</h3>
                      <p className="text-brand-gold font-black text-lg">{items.find(i => i.isPlatDuJour)?.price || 3500} F</p>
                   </div>
                </div>
            </div>

            <div className="mt-10 grid grid-cols-2 gap-4 px-6">
                <button onClick={() => setCurrentPage(Page.TRAITEUR)} className="col-span-2 bg-[#1A0F0D] h-32 rounded-[3rem] text-brand-gold flex items-center justify-between px-10 shadow-2xl group relative overflow-hidden active:scale-95 transition-all">
                   <div className="relative z-10 text-left">
                      <h4 className="font-black text-xl italic uppercase tracking-tighter leading-none mb-1">Traiteur</h4>
                      <p className="text-[9px] font-black text-white/50 uppercase tracking-[0.2em]">Événements Prestige</p>
                   </div>
                   <div className="p-4 bg-brand-gold text-brand-brown rounded-2xl relative z-10 shadow-xl group-hover:rotate-12 transition-transform"><Calendar size={28} /></div>
                </button>
                <button onClick={() => setCurrentPage(Page.MENU)} className="bg-brand-brown h-44 rounded-[4rem] text-brand-gold flex flex-col items-center justify-center gap-4 shadow-2xl transition-all active:scale-95 border-b-8 border-black/20 group">
                   <div className="p-4 bg-white/10 rounded-3xl"><ShoppingBag size={34} /></div>
                   <span className="font-black text-[11px] uppercase tracking-widest italic">La Carte</span>
                </button>
                <div className="grid grid-rows-2 gap-4">
                    <button onClick={() => setCurrentPage(Page.BOX)} className="bg-brand-orange rounded-[3rem] text-white flex items-center justify-center gap-4 font-black text-[10px] uppercase tracking-widest italic shadow-xl active:scale-95 transition-all">
                      <Package size={20} /> Box
                    </button>
                    <button onClick={() => setCurrentPage(Page.PACKS)} className="bg-brand-gold rounded-[3rem] text-brand-brown flex items-center justify-center gap-4 font-black text-[10px] uppercase tracking-widest italic shadow-xl active:scale-95 transition-all">
                      <Trophy size={20} /> Packs
                    </button>
                </div>
            </div>
            <div className="px-6 mt-12 mb-12"><DeliveryEstimator /></div>
          </div>
        );

      case Page.MENU:
      case Page.BOX:
      case Page.PACKS:
        return (
          <div className="pb-32 animate-fade-in px-6">
            <div className="flex items-center justify-between py-10">
               <button onClick={() => setCurrentPage(Page.HOME)} className="p-4 bg-white rounded-2xl shadow-xl text-brand-brown active:scale-90 transition-transform"><ArrowLeft size={20}/></button>
               <h2 className="text-2xl font-black uppercase italic tracking-tighter text-brand-brown">Nos Menus</h2>
               <div className="w-12 h-12"></div>
            </div>
            <div className="grid grid-cols-2 gap-5">
               {filteredItems.map(item => (
                 <div key={item.id} onClick={() => setSelectedItemForDetails(item)} className="bg-white rounded-[2.5rem] overflow-hidden shadow-xl border border-brand-brown/5 active:scale-95 transition-all group cursor-pointer">
                    <div className="relative aspect-square">
                       <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                    </div>
                    <div className="p-5 text-center">
                       <h4 className="font-black text-[10px] uppercase text-brand-brown truncate mb-1">{item.name}</h4>
                       <span className="text-xs font-black text-brand-orange italic">{item.price} F</span>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        );

      case Page.CART:
        return (
          <div className="pb-32 animate-fade-in px-6 flex flex-col min-h-[80vh]">
             <div className="flex items-center justify-between py-10 text-brand-brown font-black uppercase italic text-3xl tracking-tighter">Mon Panier</div>
             {cart.length === 0 ? (
               <div className="flex-1 flex flex-col items-center justify-center opacity-30 italic font-black uppercase tracking-widest">Panier vide</div>
             ) : (
               <div className="space-y-4">
                  {cart.map(item => (
                    <div key={item.id} className="bg-white p-5 rounded-[2.5rem] shadow-xl flex items-center gap-4">
                       <img src={item.image} className="w-16 h-16 rounded-xl object-cover" />
                       <div className="flex-1">
                          <h4 className="font-black text-[10px] uppercase text-brand-brown">{item.name}</h4>
                          <p className="text-[10px] font-bold text-gray-400">x{item.quantity} • {item.price * item.quantity} F</p>
                       </div>
                       <button onClick={() => removeFromCart(item.id)} className="text-red-500 p-2"><Trash2 size={16}/></button>
                    </div>
                  ))}
                  <button onClick={() => setShowUpsell(true)} className="w-full bg-brand-brown text-brand-gold py-6 rounded-[2.5rem] font-black uppercase mt-10 shadow-2xl italic">Passer la commande</button>
               </div>
             )}
          </div>
        );

      case Page.COMPTE:
        return (
          <div className="pb-32 animate-fade-in px-6 py-12 text-center">
             <div className="w-32 h-32 mx-auto rounded-[3.5rem] bg-brand-brown p-1 mb-6 border-4 border-white shadow-2xl overflow-hidden">
                {profile.photo ? <img src={profile.photo} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center"><User size={48} className="text-white/20" /></div>}
             </div>
             <h2 className="text-2xl font-black uppercase italic tracking-tighter text-brand-brown">{profile.name || "Gourmet Niamey"}</h2>
             <button onClick={() => setCurrentPage(Page.ADMIN)} className="mt-10 text-[9px] font-black uppercase tracking-[0.3em] text-brand-brown/20 flex items-center gap-2 mx-auto hover:text-brand-orange transition-colors"><Lock size={12}/> Mode Administrateur</button>
          </div>
        );

      case Page.TRAITEUR:
        return <TraiteurView />;
      default:
        return <div className="p-20 text-center font-black uppercase text-brand-brown italic opacity-20">À venir...</div>;
    }
  };

  if (showSplash) {
    return (
      <div className={`fixed inset-0 z-[100] bg-black flex items-center justify-center transition-opacity duration-1000 ${splashFade ? 'opacity-0' : 'opacity-100'}`}>
        <video autoPlay muted playsInline className="w-full h-full object-cover" onEnded={closeSplash} onError={closeSplash}>
          <source src={LOGO_VIDEO_URL} type="video/mp4" />
        </video>
        <button onClick={closeSplash} className="absolute bottom-10 right-6 bg-white/20 backdrop-blur-md text-white px-6 py-3 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-2 border border-white/20 active:scale-95 transition-all">
          Passer <SkipForward size={14} />
        </button>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-brand-cream/10 shadow-2xl overflow-hidden relative font-sans flex flex-col items-center">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <div className="flex-1 overflow-y-auto no-scrollbar scroll-smooth flex flex-col items-center w-full">
        <div className="w-full max-w-lg mx-auto bg-brand-cream/10 min-h-screen relative">{renderContent()}</div>
      </div>
      <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.length} />
      <AIChat />
      <ItemDetailsModal item={selectedItemForDetails} isOpen={!!selectedItemForDetails} onClose={() => setSelectedItemForDetails(null)} onAddToCart={handleAddToCart} />
      <UpsellModal isOpen={showUpsell} onClose={() => setShowUpsell(false)} suggestions={items.filter(i => i.category === 'Boisson' || i.category === 'Dessert').slice(0, 3)} onAdd={(it) => { handleAddToCart(it, 1, ''); setShowUpsell(false); }} onProceed={() => { setShowUpsell(false); alert("Commande validée ! (Simulé)"); setCart([]); setCurrentPage(Page.HOME); playSound('cash'); }} />
    </div>
  );
};

export default App;

import { createClient } from '@supabase/supabase-js';

// Récupération sécurisée des variables d'environnement
const supabaseUrl = (import.meta as any).env?.VITE_SUPABASE_URL || '';
const supabaseKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || '';

// Validation : Si les clés sont vides ou contiennent encore le texte par défaut "YOUR_..."
const isValid = supabaseUrl && 
                supabaseKey && 
                !supabaseUrl.includes('YOUR_SUPABASE_URL') &&
                supabaseUrl.startsWith('https://');

// Exportation du client ou de null pour permettre à l'app de fonctionner en mode dégradé (données locales)
export const supabase = isValid ? createClient(supabaseUrl, supabaseKey) : null;

if (!isValid) {
  console.warn("⚠️ Supabase non configuré. L'application utilise les données locales de secours (MENU_ITEMS dans constants.ts).");
}

export type MenuCategory = 
  | 'Entree' 
  | 'Plat Africain' 
  | 'Plat Européen' 
  | 'Spécialité Maison' 
  | 'Plat du Jour' 
  | 'Dessert' 
  | 'Boisson' 
  | 'Box Sauce'
  | 'Box Repas'
  | 'Pack'
  | 'Buffet';

export type OrderStatus = 
  | 'RECEIVED' 
  | 'CONFIRMED' 
  | 'PREPARING' 
  | 'READY' 
  | 'DELIVERING' 
  | 'DELIVERED'
  | 'CANCELLED';

export type PaymentMethod = 'CASH' | 'AIRTEL_MONEY' | 'MOOV_MONEY';

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
  image: string;
  category: MenuCategory;
  rating: number;
  isAvailable: boolean;
  isSpicy?: boolean;
  isVegetarian?: boolean;
  isPlatDuJour?: boolean;
  isSpécialitéMaison?: boolean;
  isPromo?: boolean;
  includes?: string[]; 
  minPeople?: number;  
}

export interface Review {
  id: string;
  name: string;
  comment: string;
  rating: number;
  image: string;
  date: string;
  adminReply?: string; 
}

export interface CartItem extends MenuItem {
  quantity: number;
  instructions?: string;
}

export interface Order {
  id: string;
  customerName: string;
  phone: string;
  address: string;
  district: string;
  items: CartItem[];
  total: number;
  deliveryFee: number;
  status: OrderStatus;
  paymentMethod: PaymentMethod;
  timestamp: string;
}

export enum Page {
  HOME = 'HOME',
  MENU = 'MENU',
  TRAITEUR = 'TRAITEUR',
  CART = 'CART',
  BOX = 'BOX',
  PACKS = 'PACKS',
  COMMANDES = 'COMMANDES',
  COMPTE = 'COMPTE',
  INFOS = 'INFOS',
  ADMIN = 'ADMIN'
}

export enum AdminView {
  DASHBOARD = 'DASHBOARD',
  ORDERS = 'ORDERS',
  MENU_MGMT = 'MENU_MGMT',
  BOX_SAUCES = 'BOX_SAUCES',
  PACK_BUFFET = 'PACK_BUFFET',
  CATERING = 'CATERING',
  LIVREUR = 'LIVREUR',
  AI_STRATEGY = 'AI_STRATEGY',
  CLUB_KHADY = 'CLUB_KHADY',
  SETTINGS = 'SETTINGS'
}

export interface District {
  name: string;
  zone: 'center' | 'periphery';
}

export interface CateringRequest {
  id: string;
  customer_name: string;
  phone: string;
  event_type: string;
  guests_count: number;
  event_date: string;
  location: string;
  details: string;
  status: 'PENDING' | 'CONTACTED' | 'VALIDATED' | 'COMPLETED';
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Navbar from './components/Navbar';
import AIChat from './components/AIChat';
import AdminDashboard from './components/AdminDashboard';
import DeliveryEstimator from './components/DeliveryEstimator';
import ItemDetailsModal from './components/ItemDetailsModal'; 
import TraiteurView from './components/TraiteurView';
import UpsellModal from './components/UpsellModal';
import Toast, { ToastType } from './components/Toast';
import { KhadyLogo } from './components/KhadyLogo';
import { playSound } from './utils/audio';
import { supabase } from './lib/supabase';
import { Page, MenuItem, CartItem, Review, Order, OrderStatus, PaymentMethod, MenuCategory } from './types';
import { MENU_ITEMS, REVIEWS as INITIAL_REVIEWS, RESTAURANT_INFO, LOGO_VIDEO_URL } from './constants';
import { 
  User, ShoppingBag, Trash2, Trophy, MapPin, Package, Calendar, SkipForward, ArrowLeft, Camera, LogOut, Lock, Edit3, Trash, Plus
} from 'lucide-react';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [splashFade, setSplashFade] = useState(false);
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [toast, setToast] = useState<{message: string, type: ToastType} | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => JSON.parse(localStorage.getItem('khadys_cart') || '[]'));
  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [reviews, setReviews] = useState<Review[]>(INITIAL_REVIEWS);
  const [profile, setProfile] = useState(() => {
    const saved = localStorage.getItem('khadys_profile');
    return saved ? JSON.parse(saved) : { name: 'Gourmet Niamey', phone: '', photo: null };
  });

  const [selectedItemForDetails, setSelectedItemForDetails] = useState<MenuItem | null>(null);
  const [showUpsell, setShowUpsell] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    localStorage.setItem('khadys_profile', JSON.stringify(profile));
  }, [profile]);

  useEffect(() => {
    const fetchData = async () => {
      if (!supabase) return;
      try {
        const { data: menuData } = await supabase.from('menu_items').select('*');
        if (menuData) setItems(menuData.map(m => ({ ...m, isAvailable: m.is_available })));
      } catch (e) { console.error(e); }
    };
    fetchData();
  }, []);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setProfile({ ...profile, photo: reader.result as string });
        showNotification("Photo mise à jour ! ✨");
      };
      reader.readAsDataURL(file);
    }
  };

  const closeSplash = () => {
    setSplashFade(true);
    setTimeout(() => setShowSplash(false), 800);
  };

  const showNotification = (message: string, type: ToastType = 'success') => setToast({ message, type });

  const filteredItems = useMemo(() => {
    if (currentPage === Page.BOX) return items.filter(i => i.category === 'Box Repas' || i.category === 'Box Sauce');
    if (currentPage === Page.PACKS) return items.filter(i => i.category === 'Pack' || i.category === 'Buffet');
    return items.filter(i => i.category !== 'Box Repas' && i.category !== 'Box Sauce' && i.category !== 'Pack' && i.category !== 'Buffet');
  }, [items, currentPage]);

  const handleAddToCart = (item: MenuItem, quantity: number, instructions: string) => {
    const existing = cart.find(c => c.id === item.id);
    if (existing) {
      setCart(cart.map(c => c.id === item.id ? { ...c, quantity: c.quantity + quantity, instructions } : c));
    } else {
      setCart([...cart, { ...item, quantity, instructions }]);
    }
    playSound('pop');
    showNotification(`${item.name} ajouté !`);
  };

  const renderContent = () => {
    if (currentPage === Page.ADMIN) {
      return <AdminDashboard items={items} setItems={setItems} orders={orders} setOrders={setOrders} reviews={reviews} setReviews={setReviews} onExit={() => setCurrentPage(Page.HOME)} />;
    }

    switch(currentPage) {
      case Page.HOME:
        return (
          <div className="pb-32 animate-fade-in w-full">
            <div className="flex justify-between items-center py-6 px-6 bg-brand-cream/80 backdrop-blur-md sticky top-0 z-40">
              <KhadyLogo />
              <button onClick={() => setCurrentPage(Page.COMPTE)} className="w-12 h-12 rounded-2xl border-2 border-brand-brown/10 overflow-hidden shadow-lg bg-white p-0.5">
                {profile.photo ? <img src={profile.photo} className="w-full h-full object-cover rounded-xl" /> : <User className="w-full h-full p-2 text-brand-brown/30" />}
              </button>
            </div>

            <div className="mt-8 px-6">
                <div className="relative w-full aspect-[16/10] rounded-[3.5rem] overflow-hidden shadow-2xl border-4 border-white group cursor-pointer" onClick={() => setSelectedItemForDetails(items.find(i => i.is_plat_du_jour) || items[0])}>
                   <img src={items.find(i => i.isPlatDuJour)?.image || items[0].image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                   <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent"></div>
                   <div className="absolute bottom-8 left-8 text-white">
                      <span className="bg-brand-orange text-[9px] font-black uppercase px-3 py-1 rounded-full mb-3 inline-block animate-bounce shadow-lg">Plat du Jour 🥘</span>
                      <h3 className="text-2xl font-black uppercase italic tracking-tighter mb-1">{items.find(i => i.isPlatDuJour)?.name || "Menu Spécial"}</h3>
                      <p className="text-brand-gold font-black text-lg">{items.find(i => i.isPlatDuJour)?.price || 3500} F</p>
                   </div>
                </div>
