                       <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                       {item.isSpécialitéMaison && <span className="absolute top-4 left-4 bg-brand-gold text-brand-brown font-black text-[7px] px-3 py-1 rounded-full uppercase shadow-lg">Étoilé 🌟</span>}
                    </div>
                    <div className="p-5 text-center">
                       <h4 className="font-black text-[10px] uppercase text-brand-brown truncate mb-1">{item.name}</h4>
                       <span className="text-xs font-black text-brand-orange italic">{item.price} F</span>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        );

      case Page.COMPTE:
        return (
          <div className="pb-32 animate-fade-in px-6 py-12 flex flex-col items-center">
             <div className="relative mb-8 group">
                <div className="w-40 h-40 rounded-[4rem] bg-brand-brown p-1 border-4 border-white shadow-2xl overflow-hidden relative">
                   {profile.photo ? <img src={profile.photo} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center"><User size={64} className="text-white/10" /></div>}
                   <button onClick={() => fileInputRef.current?.click()} className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity text-white">
                      <Camera size={32} />
                   </button>
                </div>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handlePhotoUpload} />
             </div>

             <h2 className="text-3xl font-black text-brand-brown italic uppercase mb-2 tracking-tighter">{profile.name}</h2>
             <p className="text-[10px] font-black text-brand-orange uppercase tracking-[0.3em] mb-12">Membre Club Khady Gold</p>

             <div className="w-full space-y-4">
                <div className="bg-white p-6 rounded-[2.5rem] shadow-xl flex items-center justify-between border border-brand-brown/5">
                   <div>
                      <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Mes Points</p>
                      <h4 className="text-2xl font-black text-brand-brown italic">1,250 PTS</h4>
                   </div>
                   <div className="p-4 bg-brand-gold/10 text-brand-gold rounded-2xl"><Trophy size={24} /></div>
                </div>

                <button onClick={() => setCurrentPage(Page.ADMIN)} className="w-full p-6 bg-brand-brown text-brand-gold rounded-[2.5rem] flex items-center justify-between shadow-xl">
                   <div className="flex items-center gap-4">
                      <Lock size={20} />
                      <span className="font-black uppercase text-xs italic">Panel Administrateur</span>
                   </div>
                   <Lock size={16} />
                </button>
             </div>
          </div>
        );

      case Page.TRAITEUR:
        return <TraiteurView />;
      case Page.CART:
        return (
          <div className="pb-32 animate-fade-in px-6 flex flex-col min-h-[80vh]">
             <div className="flex items-center justify-between py-10 text-brand-brown font-black uppercase italic text-3xl tracking-tighter">Panier</div>
             {cart.length === 0 ? (
               <div className="flex-1 flex flex-col items-center justify-center italic opacity-20 font-black uppercase text-xl">Vide</div>
             ) : (
               <div className="space-y-4">
                  {cart.map(item => (
                    <div key={item.id} className="bg-white p-5 rounded-[2.5rem] shadow-xl flex items-center gap-4 border border-brand-brown/5">
                       <img src={item.image} className="w-16 h-16 rounded-xl object-cover" />
                       <div className="flex-1">
                          <h4 className="font-black text-[10px] uppercase text-brand-brown">{item.name}</h4>
                          <p className="text-[10px] font-bold text-gray-400">x{item.quantity} • {item.price * item.quantity} F</p>
                       </div>
                       <button onClick={() => setCart(cart.filter(c => c.id !== item.id))} className="text-red-500 p-2"><Trash2 size={16}/></button>
                    </div>
                  ))}
                  <button onClick={() => setShowUpsell(true)} className="w-full bg-brand-brown text-brand-gold py-6 rounded-[2.5rem] font-black uppercase mt-10 shadow-2xl italic">Valider la commande</button>
               </div>
             )}
          </div>
        );
      default: return null;
    }
  };

  if (showSplash) {
    return (
      <div className={`fixed inset-0 z-[100] bg-black flex items-center justify-center transition-opacity duration-1000 ${splashFade ? 'opacity-0' : 'opacity-100'}`}>
        <video autoPlay muted playsInline className="w-full h-full object-cover" onEnded={closeSplash} onError={closeSplash}>
          <source src={LOGO_VIDEO_URL} type="video/mp4" />
        </video>
        <button onClick={closeSplash} className="absolute bottom-10 right-6 bg-white/20 backdrop-blur-md text-white px-6 py-3 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-2 border border-white/20">Passer <SkipForward size={14} /></button>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-brand-cream/10 shadow-2xl overflow-hidden relative font-sans flex flex-col items-center">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <div className="flex-1 overflow-y-auto no-scrollbar w-full max-w-lg bg-brand-cream/10 min-h-screen relative">{renderContent()}</div>
      <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.length} />
      <AIChat />
      <ItemDetailsModal item={selectedItemForDetails} isOpen={!!selectedItemForDetails} onClose={() => setSelectedItemForDetails(null)} onAddToCart={handleAddToCart} />
      <UpsellModal isOpen={showUpsell} onClose={() => setShowUpsell(false)} suggestions={items.filter(i => i.category === 'Boisson' || i.category === 'Dessert').slice(0, 3)} onAdd={(it) => handleAddToCart(it, 1, '')} onProceed={() => { setShowUpsell(false); alert("Commande simulée avec succès !"); setCart([]); setCurrentPage(Page.HOME); playSound('cash'); }} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, ShoppingBag, Utensils, Box, Layers, Calendar, Bike, Sparkles, Users, Settings, 
  X, CheckCircle, TrendingUp, Clock, Phone, MapPin, Plus, Edit3, Trash, Save, MessageSquare, Shield
} from 'lucide-react';
import { MenuItem, AdminView, Order, OrderStatus, Review, CateringRequest, MenuCategory } from '../types';
import { playSound } from '../utils/audio';
import { KhadyLogo } from './KhadyLogo';
import { supabase } from '../lib/supabase';

interface AdminDashboardProps {
  items: MenuItem[];
  setItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
  reviews: Review[];
  setReviews: React.Dispatch<React.SetStateAction<Review[]>>;
  onExit: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  items, setItems, orders, setOrders, reviews, setReviews, onExit 
}) => {
  const [currentView, setCurrentView] = useState<AdminView>(AdminView.DASHBOARD);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [password, setPassword] = useState('');
  const [caterings, setCaterings] = useState<CateringRequest[]>([]);
  const [aiInstruction, setAiInstruction] = useState("Tu es Khady IA, l'assistante culinaire de Niamey...");

  const sidebarItems = [
    { view: AdminView.DASHBOARD, icon: LayoutDashboard, label: 'Dashboard' },
    { view: AdminView.ORDERS, icon: ShoppingBag, label: 'Commandes' },
    { view: AdminView.MENU_MGMT, icon: Utensils, label: 'Plats' },
    { view: AdminView.BOX_SAUCES, icon: Box, label: 'Box Sauces' },
    { view: AdminView.PACK_BUFFET, icon: Layers, label: 'Packs' },
    { view: AdminView.CATERING, icon: Calendar, label: 'Traiteur' },
    { view: AdminView.LIVREUR, icon: Bike, label: 'Livreur' },
    { view: AdminView.AI_STRATEGY, icon: Sparkles, label: 'IA Strategy' },
    { view: AdminView.CLUB_KHADY, icon: Users, label: 'Club' },
    { view: AdminView.SETTINGS, icon: Settings, label: 'Settings' },
  ];

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === 'khadysfood') {
      setIsLoggedIn(true);
      playSound('success');
    } else {
      alert("Mot de passe incorrect.");
    }
  };

  const deleteItem = async (id: string) => {
    if (confirm("Supprimer ce plat ?")) {
      setItems(items.filter(i => i.id !== id));
      if (supabase) await supabase.from('menu_items').delete().eq('id', id);
      playSound('pop');
    }
  };

  const toggleAvailability = async (id: string) => {
    const item = items.find(i => i.id === id);
    if (!item) return;
    const newStatus = !item.isAvailable;
    setItems(items.map(i => i.id === id ? { ...i, isAvailable: newStatus } : i));
    if (supabase) await supabase.from('menu_items').update({ is_available: newStatus }).eq('id', id);
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-[#1A0F0D] flex items-center justify-center p-6 text-white animate-fade-in">
        <div className="bg-white/5 p-12 rounded-[5rem] w-full max-w-sm text-center border border-white/10 shadow-2xl">
          <KhadyLogo variant="light" className="mb-10 scale-75 justify-center" />
          <h2 className="text-xl font-black uppercase italic text-brand-gold mb-8">Espace Admin</h2>
          <form onSubmit={handleLogin} className="space-y-6">
            <input type="password" placeholder="Mot de passe" className="w-full p-6 bg-white/5 rounded-[2rem] text-white outline-none font-bold text-center border border-white/10 focus:border-brand-orange transition-all" value={password} onChange={e => setPassword(e.target.value)} />
            <button className="w-full bg-brand-orange text-white py-6 rounded-[2rem] font-black uppercase shadow-xl active:scale-95 transition-all">Connexion</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#1A0F0D] flex flex-col text-white overflow-hidden animate-fade-in">
      {/* HEADER FIXE */}
      <div className="p-6 flex justify-between items-center border-b border-white/5 bg-[#1A0F0D]/95 backdrop-blur-lg z-50">
         <KhadyLogo variant="light" className="scale-75" />
         <button onClick={onExit} className="p-4 bg-red-500/20 text-red-500 rounded-2xl active:scale-90 transition-transform"><X size={20} /></button>
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* SIDEBAR TABS */}
        <div className="w-20 bg-white/5 border-r border-white/5 flex flex-col items-center py-6 gap-6 overflow-y-auto no-scrollbar">
          {sidebarItems.map(item => (
            <button key={item.view} onClick={() => { setCurrentView(item.view); playSound('pop'); }} className={`p-4 rounded-2xl transition-all relative group ${currentView === item.view ? 'bg-brand-orange text-white shadow-lg scale-110' : 'text-white/30 hover:bg-white/10'}`}>
              <item.icon size={20} />
              <span className="absolute left-24 bg-brand-brown text-white text-[10px] px-3 py-1 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-50 font-black uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </div>

        {/* MAIN CONTENT AREA */}
        <div className="flex-1 overflow-y-auto p-8 no-scrollbar pb-32">
          {currentView === AdminView.DASHBOARD && (
            <div className="space-y-8">
               <div className="grid grid-cols-2 gap-4">
                  <div className="bg-white/5 p-8 rounded-[4rem] border border-white/5 text-center">
                     <TrendingUp className="text-brand-orange mx-auto mb-3" size={32} />
                     <p className="text-[10px] text-white/40 uppercase font-black mb-1 tracking-widest">CA du Jour</p>
                     <h4 className="text-3xl font-black italic">450.000 F</h4>
