                  <div className="bg-white/5 p-8 rounded-[4rem] border border-white/5 text-center">
                     <ShoppingBag className="text-brand-gold mx-auto mb-3" size={32} />
                     <p className="text-[10px] text-white/40 uppercase font-black mb-1 tracking-widest">Commandes</p>
                     <h4 className="text-3xl font-black italic">12</h4>
