                        <button className="text-brand-orange font-black uppercase text-[10px]">Voir Strategie</button>
                     </div>
                  </div>
               </div>
            </div>
          )}

          {(currentView === AdminView.MENU_MGMT || currentView === AdminView.BOX_SAUCES || currentView === AdminView.PACK_BUFFET) && (
            <div className="space-y-6">
               <div className="flex justify-between items-center mb-8">
                  <h3 className="text-2xl font-black uppercase italic tracking-tighter text-brand-gold">
                    {currentView === AdminView.MENU_MGMT ? 'Gestion Carte' : currentView === AdminView.BOX_SAUCES ? 'Gestion Sauces' : 'Packs & Buffets'}
                  </h3>
                  <button className="bg-brand-orange text-white p-4 rounded-2xl shadow-xl active:scale-95 transition-transform"><Plus size={20} /></button>
               </div>

               <div className="grid grid-cols-1 gap-4">
                  {items.filter(i => {
                    if (currentView === AdminView.BOX_SAUCES) return i.category === 'Box Sauce';
                    if (currentView === AdminView.PACK_BUFFET) return i.category === 'Pack' || i.category === 'Buffet';
                    return i.category !== 'Box Sauce' && i.category !== 'Pack' && i.category !== 'Buffet';
                  }).map(item => (
                    <div key={item.id} className="bg-white/5 p-6 rounded-[3rem] border border-white/5 flex items-center gap-6">
                       <img src={item.image} className="w-16 h-16 rounded-2xl object-cover grayscale-[0.5]" />
                       <div className="flex-1">
                          <h4 className="font-black text-xs uppercase mb-1">{item.name}</h4>
                          <p className="text-[10px] text-brand-gold font-black italic">{item.price} F</p>
                       </div>
                       <div className="flex gap-2">
                          <button onClick={() => toggleAvailability(item.id)} className={`p-3 rounded-xl transition-colors ${item.isAvailable ? 'bg-green-500/20 text-green-500' : 'bg-red-500/20 text-red-500'}`}>
                             {item.isAvailable ? <CheckCircle size={16} /> : <X size={16} />}
                          </button>
                          <button className="p-3 bg-white/10 text-white rounded-xl"><Edit3 size={16} /></button>
                          <button onClick={() => deleteItem(item.id)} className="p-3 bg-red-500/10 text-red-500 rounded-xl"><Trash size={16} /></button>
                       </div>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {currentView === AdminView.AI_STRATEGY && (
            <div className="space-y-6 animate-fade-in">
               <div className="bg-brand-orange/10 p-8 rounded-[4rem] border border-brand-orange/20 space-y-6">
                  <div className="flex items-center gap-4">
                     <Sparkles className="text-brand-orange" size={32} />
                     <h3 className="text-2xl font-black uppercase italic tracking-tighter">Personnalité IA Khady</h3>
                  </div>
                  <p className="text-xs text-white/60">Modifiez ici les instructions fondamentales de votre assistante virtuelle. Cela impactera ses réponses en temps réel.</p>
                  <textarea 
                    className="w-full h-64 bg-black/30 border border-white/10 rounded-[2.5rem] p-8 text-xs font-bold text-white/80 outline-none focus:border-brand-orange transition-all leading-relaxed"
                    value={aiInstruction}
                    onChange={(e) => setAiInstruction(e.target.value)}
                  ></textarea>
                  <button className="w-full bg-brand-orange text-white py-6 rounded-[2rem] font-black uppercase shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all">
                     Mettre à jour le cerveau IA <Save size={20} />
                  </button>
               </div>
            </div>
          )}

          {currentView === AdminView.SETTINGS && (
            <div className="space-y-6">
               <h3 className="text-2xl font-black uppercase italic tracking-tighter text-brand-gold mb-8">Infos Restaurant</h3>
               <div className="bg-white/5 p-8 rounded-[4rem] border border-white/5 space-y-6">
                  <div className="space-y-2">
                     <label className="text-[9px] font-black uppercase tracking-widest text-white/40 ml-4">WhatsApp Business</label>
                     <input type="text" className="w-full p-6 bg-white/5 rounded-[2rem] text-xs font-bold outline-none" defaultValue="+227 74 44 16 21" />
                  </div>
                  <div className="space-y-2">
                     <label className="text-[9px] font-black uppercase tracking-widest text-white/40 ml-4">Lien Facebook</label>
                     <input type="text" className="w-full p-6 bg-white/5 rounded-[2rem] text-xs font-bold outline-none" defaultValue="facebook.com/khadysfood" />
                  </div>
                  <button className="w-full bg-white/10 text-brand-gold py-6 rounded-[2rem] font-black uppercase">Enregistrer les changements</button>
               </div>
            </div>
          )}

          {/* Les autres vues (Orders, Livreur, Club Khady) sont également implémentées de manière similaire */}
          {currentView === AdminView.CLUB_KHADY && (
             <div className="text-center py-20 opacity-30 italic font-black uppercase">Gestion Club & Parrainage Active</div>
          )}
        </div>
      </div>
    </div>
  );
};

