                     <div key={idx} onClick={() => setSelectedItemForDetails(item)} className="inline-block w-72 h-44 rounded-[2.5rem] overflow-hidden shadow-xl border-4 border-white flex-shrink-0 cursor-pointer active:scale-95 transition-transform">
                        <img src={item.image} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
