    const existing = cart.find(c => c.id === item.id);
    if (existing) {
      setCart(cart.map(c => c.id === item.id ? { ...c, quantity: c.quantity + quantity, instructions } : c));
    } else {
      setCart([...cart, { ...item, quantity, instructions }]);
    }
    playSound('pop');
    showNotification(`${item.name} ajouté !`);
  };

