      address: 'Niamey, Plateau',
      district: 'Plateau',
      items: [...cart],
      total: cart.reduce((acc, i) => acc + (i.price * i.quantity), 0),
      deliveryFee: 1000,
      status: 'RECEIVED',
      paymentMethod: 'CASH',
      timestamp: new Date().toISOString()
    };

    setOrders([newOrder, ...orders]);
    setActiveOrder(newOrder);
