import React, { useState, useEffect } from 'react';
import { Order, OrderStatus } from '../types';
import { playSound } from '../utils/audio';
import { Clock, CheckCircle2, ChefHat, Bike, PackageCheck, Box } from 'lucide-react';

interface OrderTrackingProps {
  order: Order;
  onComplete: () => void;
}

// Moved declaration before usage in steps array
const Smile = () => <div className="text-xl">🤩</div>;

const steps: { status: OrderStatus; label: string; icon: any; sound: any }[] = [
  { status: 'RECEIVED', label: 'Commande Reçue', icon: Box, sound: 'pop' },
  { status: 'CONFIRMED', label: 'Confirmée', icon: CheckCircle2, sound: 'notification' },
  { status: 'PREPARING', label: 'En Cuisine', icon: ChefHat, sound: 'notification' },
  { status: 'READY', label: 'Prête !', icon: PackageCheck, sound: 'success' },
  { status: 'DELIVERING', label: 'En Livraison', icon: Bike, sound: 'delivery' },
  { status: 'DELIVERED', label: 'Livrée', icon: Smile, sound: 'success' }
];

const OrderTracking: React.FC<OrderTrackingProps> = ({ order, onComplete }) => {
  const [currentStepIdx, setCurrentStepIdx] = useState(0);

  useEffect(() => {
    if (currentStepIdx < steps.length - 1) {
      const timer = setTimeout(() => {
        const nextIdx = currentStepIdx + 1;
        setCurrentStepIdx(nextIdx);
        playSound(steps[nextIdx].sound);

        // Simuler la notification admin lors de la livraison
        if (steps[nextIdx].status === 'DELIVERED') {
          console.log("DRIVER NOTIFICATION SENT TO ADMIN");
          onComplete();
        }
      }, 5000); // 5 secondes par étape pour la démo
      return () => clearTimeout(timer);
    }
  }, [currentStepIdx]);

  return (
    <div className="bg-white p-8 rounded-[3.5rem] shadow-2xl border border-brand-brown/5 relative overflow-hidden">
      <div className="absolute top-0 right-0 w-32 h-32 bg-brand-orange/5 rounded-full -mr-16 -mt-16"></div>

      <div className="flex justify-between items-center mb-10 relative z-10">
         <div>
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">ID Commande</h4>
            <p className="text-xl font-black italic text-brand-brown">{order.id}</p>
         </div>
         <div className="p-4 bg-brand-brown rounded-2xl text-brand-gold animate-bounce-slow">
            <Clock size={24} />
         </div>
      </div>

      <div className="relative space-y-8">
         {/* Ligne verticale de progression */}
         <div className="absolute left-6 top-2 bottom-2 w-1 bg-gray-100 rounded-full">
            <div 
               className="w-full bg-brand-orange transition-all duration-1000 rounded-full" 
               style={{ height: `${(currentStepIdx / (steps.length - 1)) * 100}%` }}
            ></div>
         </div>

         {steps.map((step, idx) => {
            const isCompleted = idx < currentStepIdx;
            const isCurrent = idx === currentStepIdx;
            const Icon = step.icon;

            return (
               <div key={idx} className={`flex items-center gap-6 transition-all duration-500 ${isCurrent ? 'scale-105' : 'opacity-40'}`}>
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center relative z-10 shadow-lg border-2 ${isCurrent || isCompleted ? 'bg-brand-orange text-white border-white' : 'bg-white text-gray-300 border-gray-100'}`}>
                     {isCompleted ? <CheckCircle2 size={24} /> : <Icon size={24} />}
                  </div>
                  <div>
                     <p className={`text-[10px] font-black uppercase tracking-widest ${isCurrent || isCompleted ? 'text-brand-orange' : 'text-gray-400'}`}>
                        Étape {idx + 1}
                     </p>
                     <p className={`text-sm font-black italic ${isCurrent || isCompleted ? 'text-brand-brown' : 'text-gray-300'}`}>
                        {step.label}
                     </p>
                  </div>
               </div>
            );
         })}
      </div>
    </div>
  );
};

