                    <div className="p-5 text-center">
                       <h4 className="font-black text-[10px] uppercase text-brand-brown truncate mb-1">{item.name}</h4>
                       <span className="text-xs font-black text-brand-orange italic">{item.price} F</span>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        );

      case Page.TRAITEUR: return <TraiteurView />;
      default: return null;
    }
  };

  if (showSplash) {
    return (
      <div className={`fixed inset-0 z-[100] bg-black flex items-center justify-center transition-opacity duration-1000 ${splashFade ? 'opacity-0' : 'opacity-100'}`}>
        <video autoPlay muted playsInline className="w-full h-full object-cover" onEnded={closeSplash} onError={closeSplash}>
          <source src={LOGO_VIDEO_URL} type="video/mp4" />
        </video>
        <button onClick={closeSplash} className="absolute bottom-10 right-6 bg-white/20 backdrop-blur-md text-white px-6 py-3 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-2 border border-white/20">Passer <SkipForward size={14} /></button>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-brand-cream/10 shadow-2xl overflow-hidden relative font-sans flex flex-col items-center">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <div className="flex-1 overflow-y-auto no-scrollbar w-full max-w-lg bg-brand-cream/10 min-h-screen relative">{renderContent()}</div>
      <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.length} />
      <AIChat />
      <ItemDetailsModal item={selectedItemForDetails} isOpen={!!selectedItemForDetails} onClose={() => setSelectedItemForDetails(null)} onAddToCart={handleAddToCart} />
      <UpsellModal isOpen={showUpsell} onClose={() => setShowUpsell(false)} suggestions={items.filter(i => i.category === 'Boisson').slice(0, 3)} onAdd={handleAddToCart} onProceed={handleCheckout} />
      {showReceipt && activeOrder && <Receipt order={activeOrder} onClose={() => setShowReceipt(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Order, OrderStatus } from '../types';
import { playSound } from '../utils/audio';
import { Clock, CheckCircle2, ChefHat, Bike, PackageCheck, Box, Bell } from 'lucide-react';

interface OrderTrackingProps {
  order: Order;
  onComplete: () => void;
}

const Smile = () => <div className="text-xl animate-bounce">🤩</div>;

const steps: { status: OrderStatus; label: string; icon: any; sound: any }[] = [
  { status: 'RECEIVED', label: 'Reçu', icon: Box, sound: 'pop' },
  { status: 'CONFIRMED', label: 'Confirmé', icon: CheckCircle2, sound: 'notification' },
  { status: 'PREPARING', label: 'En Cuisine', icon: ChefHat, sound: 'notification' },
  { status: 'READY', label: 'Prêt !', icon: PackageCheck, sound: 'success' },
  { status: 'DELIVERING', label: 'En route', icon: Bike, sound: 'delivery' },
  { status: 'DELIVERED', label: 'Livré !', icon: Smile, sound: 'success' }
];

const OrderTracking: React.FC<OrderTrackingProps> = ({ order, onComplete }) => {
  const [currentStepIdx, setCurrentStepIdx] = useState(0);

  useEffect(() => {
    if (currentStepIdx < steps.length - 1) {
      const timer = setTimeout(() => {
        const nextIdx = currentStepIdx + 1;
        setCurrentStepIdx(nextIdx);
        playSound(steps[nextIdx].sound);

        // Alerte Admin visuelle & sonore (simulée ici par un log)
        if (steps[nextIdx].status === 'DELIVERED') {
          console.log("ALERT ADMIN : COMMANDE " + order.id + " LIVRÉE !");
          onComplete();
        }
      }, 7000); 
      return () => clearTimeout(timer);
    }
  }, [currentStepIdx]);

  return (
    <div className="bg-white p-8 rounded-[3.5rem] shadow-2xl border border-brand-brown/5 relative overflow-hidden">
      <div className="absolute top-0 right-0 w-32 h-32 bg-brand-orange/5 rounded-full -mr-16 -mt-16"></div>

      <div className="flex justify-between items-center mb-10 relative z-10">
         <div>
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Commande N°</h4>
            <p className="text-xl font-black italic text-brand-brown">{order.id}</p>
         </div>
         <div className="p-4 bg-brand-brown rounded-2xl text-brand-gold animate-pulse">
            <Clock size={24} />
         </div>
      </div>

      <div className="relative space-y-8">
         {/* Barre de progression verticale */}
         <div className="absolute left-6 top-2 bottom-2 w-1.5 bg-gray-50 rounded-full">
            <div 
               className="w-full bg-brand-orange transition-all duration-[2000ms] rounded-full shadow-[0_0_10px_rgba(255,111,0,0.5)]" 
               style={{ height: `${(currentStepIdx / (steps.length - 1)) * 100}%` }}
            ></div>
         </div>

         {steps.map((step, idx) => {
            const isCompleted = idx < currentStepIdx;
            const isCurrent = idx === currentStepIdx;
            const Icon = step.icon;

            return (
               <div key={idx} className={`flex items-center gap-6 transition-all duration-700 ${isCurrent ? 'scale-105 translate-x-2' : 'opacity-40'}`}>
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center relative z-10 shadow-lg border-4 transition-all ${isCurrent || isCompleted ? 'bg-brand-orange text-white border-white scale-110' : 'bg-white text-gray-300 border-gray-50'}`}>
                     {isCompleted ? <CheckCircle2 size={24} /> : <Icon size={24} />}
                  </div>
                  <div>
                     <p className={`text-[9px] font-black uppercase tracking-widest ${isCurrent || isCompleted ? 'text-brand-orange' : 'text-gray-400'}`}>
                        Étape {idx + 1}
                     </p>
                     <p className={`text-sm font-black italic ${isCurrent || isCompleted ? 'text-brand-brown' : 'text-gray-300'}`}>
                        {step.label}
                     </p>
                  </div>
               </div>
            );
         })}
      </div>

      {currentStepIdx === 5 && (
        <div className="mt-10 p-5 bg-green-50 rounded-[2rem] border border-green-100 flex items-center gap-4 animate-bounce">
           <div className="w-10 h-10 bg-green-500 rounded-xl flex items-center justify-center text-white"><Bell size={20}/></div>
           <p className="text-[10px] font-black text-green-700 uppercase tracking-widest">Notification Livreur Envoyée !</p>
        </div>
      )}
    </div>
  );
};

export default OrderTracking;

