                        <div className="flex gap-4 items-center">
                           <img src={rev.image} className="w-10 h-10 rounded-full object-cover" />
                           <div>
                              <p className="text-xs font-black text-white uppercase">{rev.name}</p>
                              <div className="flex gap-0.5 text-brand-gold">
                                 {[...Array(5)].map((_, i) => <Star key={i} size={8} fill={i < rev.rating ? "currentColor" : "none"} />)}
                              </div>
                           </div>
                        </div>
                        <div className="flex gap-2">
                           <button className="p-3 bg-red-500/10 rounded-xl text-red-500 hover:bg-red-500/20"><Trash size={16}/></button>
                        </div>
                     </div>
                     <p className="text-xs text-white/60 italic font-bold">"{rev.comment}"</p>
                  </div>
                ))}
             </div>
          </div>
        );

      default: return <div className="text-center py-20 opacity-20 italic font-black uppercase text-white">Interface en construction...</div>;
    }
  };

  return (
    <div className="min-h-screen bg-[#1A0F0D] flex flex-col text-white overflow-hidden animate-fade-in">
      <div className="p-6 flex justify-between items-center border-b border-white/5 bg-[#1A0F0D]/95 backdrop-blur-lg z-50">
         <KhadyLogo variant="light" className="scale-75" />
         <button onClick={onExit} className="p-4 bg-red-500/20 text-red-500 rounded-2xl active:scale-90 transition-transform"><X size={20} /></button>
      </div>

      <div className="flex flex-1 overflow-hidden">
        <div className="w-20 bg-white/5 border-r border-white/5 flex flex-col items-center py-6 gap-6 overflow-y-auto no-scrollbar">
          {sidebarItems.map(item => (
            <button key={item.view} onClick={() => { setCurrentView(item.view); playSound('pop'); }} className={`p-4 rounded-2xl transition-all relative group ${currentView === item.view ? 'bg-brand-orange text-white shadow-lg scale-110' : 'text-white/30 hover:bg-white/10'}`}>
              <item.icon size={20} />
              <span className="absolute left-24 bg-brand-brown text-white text-[10px] px-3 py-1 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-50 font-black uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </div>
        <div className="flex-1 overflow-y-auto p-8 no-scrollbar pb-32">
           {renderSection()}
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Navbar from './components/Navbar';
import AIChat from './components/AIChat';
import AdminDashboard from './components/AdminDashboard';
import DeliveryEstimator from './components/DeliveryEstimator';
import ItemDetailsModal from './components/ItemDetailsModal'; 
import TraiteurView from './components/TraiteurView';
import UpsellModal from './components/UpsellModal';
import OrderTracking from './components/OrderTracking';
import Receipt from './components/Receipt';
import Toast, { ToastType } from './components/Toast';
import { KhadyLogo } from './components/KhadyLogo';
import { playSound } from './utils/audio';
import { Page, MenuItem, CartItem, Review, Order, OrderStatus } from './types';
import { MENU_ITEMS, REVIEWS as INITIAL_REVIEWS, LOGO_VIDEO_URL } from './constants';
import { 
  User, ShoppingBag, Trophy, Package, Calendar, SkipForward, ArrowLeft, Camera, Lock, Star, MessageSquare, Plus, ChevronRight, Settings
} from 'lucide-react';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [splashFade, setSplashFade] = useState(false);
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [toast, setToast] = useState<{message: string, type: ToastType} | null>(null);
  const [greeting, setGreeting] = useState('Salam');

  const [cart, setCart] = useState<CartItem[]>(() => JSON.parse(localStorage.getItem('khadys_cart') || '[]'));
  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [showReceipt, setShowReceipt] = useState(false);
  const [reviews, setReviews] = useState<Review[]>(INITIAL_REVIEWS);
  const [profile, setProfile] = useState(() => {
    const saved = localStorage.getItem('khadys_profile');
    return saved ? JSON.parse(saved) : { name: 'Gourmet Niamey', phone: '', photo: null };
  });

  const [selectedItemForDetails, setSelectedItemForDetails] = useState<MenuItem | null>(null);
  const [showUpsell, setShowUpsell] = useState(false);
  const [heroIdx, setHeroIdx] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const greetingTimer = setTimeout(() => setGreeting('Bonjour'), 3500);
    const heroTimer = setInterval(() => setHeroIdx(prev => (prev + 1) % MENU_ITEMS.length), 5000);
    return () => {
      clearTimeout(greetingTimer);
      clearInterval(heroTimer);
    };
  }, []);

  const closeSplash = () => {
    setSplashFade(true);
    setTimeout(() => setShowSplash(false), 800);
  };

  const showNotification = (message: string, type: ToastType = 'success') => setToast({ message, type });

  const filteredItems = useMemo(() => {
    if (currentPage === Page.BOX) return items.filter(i => i.category === 'Box Sauce' || i.category === 'Box Repas');
    if (currentPage === Page.PACKS) return items.filter(i => i.category === 'Pack' || i.category === 'Buffet');
    return items;
  }, [items, currentPage]);

  const handleAddToCart = (item: MenuItem, quantity: number, instructions: string) => {
    const existing = cart.find(c => c.id === item.id);
    if (existing) {
      setCart(cart.map(c => c.id === item.id ? { ...c, quantity: c.quantity + quantity, instructions } : c));
    } else {
      setCart([...cart, { ...item, quantity, instructions }]);
    }
    playSound('pop');
    showNotification(`${item.name} ajouté !`);
  };

  const handleCheckout = () => {
    const newOrder: Order = {
      id: `KH-${Math.floor(Math.random() * 9000) + 1000}`,
      customerName: profile.name,
      phone: profile.phone || 'Non renseigné',
      address: 'Niamey, Plateau',
      district: 'Plateau',
      items: [...cart],
      total: cart.reduce((acc, i) => acc + (i.price * i.quantity), 0),
      deliveryFee: 1000,
      status: 'RECEIVED',
      paymentMethod: 'CASH',
      timestamp: new Date().toISOString()
    };

    setOrders([newOrder, ...orders]);
    setActiveOrder(newOrder);
    setCart([]);
    setShowUpsell(false);
    playSound('cash');
    setCurrentPage(Page.COMMANDES);
    showNotification("Commande reçue ! Suivez votre livreur.", "info");
  };

  const renderContent = () => {
    if (currentPage === Page.ADMIN) {
      return <AdminDashboard items={items} setItems={setItems} orders={orders} setOrders={setOrders} reviews={reviews} setReviews={setReviews} onExit={() => setCurrentPage(Page.HOME)} />;
    }

    switch(currentPage) {
      case Page.HOME:
        return (
          <div className="pb-32 animate-fade-in w-full">
            <div className="flex justify-between items-center py-6 px-6 bg-brand-cream/80 backdrop-blur-md sticky top-0 z-40">
              <KhadyLogo />
              <div className="flex items-center gap-3">
                 <div className="text-right">
                    <p className="text-[10px] font-black uppercase text-brand-orange tracking-widest leading-none mb-1 transition-all duration-700">
                      {greeting} <span className="inline-block animate-wave">👋🏾</span>
                    </p>
                    <p className="text-[8px] font-bold text-brand-brown/40 uppercase">C'est le goût !</p>
                 </div>
                 <button onClick={() => setCurrentPage(Page.COMPTE)} className="w-12 h-12 rounded-2xl border-2 border-brand-brown/10 overflow-hidden shadow-lg bg-white p-0.5">
                   {profile.photo ? <img src={profile.photo} className="w-full h-full object-cover rounded-xl" /> : <User className="w-full h-full p-2 text-brand-brown/30" />}
                 </button>
              </div>
            </div>

            {/* HERO : CADRE RECTANGULAIRE ANIMÉ EN CONTINU */}
            <div className="mt-8 px-6">
               <div className="relative w-full aspect-[16/10] rounded-[3.5rem] overflow-hidden shadow-2xl border-4 border-white group">
                  <div className="absolute inset-0 transition-opacity duration-1000">
                     <img src={MENU_ITEMS[heroIdx].image} className="w-full h-full object-cover animate-pulse-slow" />
                  </div>
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent"></div>
                  <div className="absolute bottom-8 left-8 text-white transition-all duration-500">
                     <span className="bg-brand-orange text-[9px] font-black uppercase px-3 py-1 rounded-full mb-3 inline-block shadow-lg">Suggestion du Chef 🥘</span>
                     <h3 className="text-2xl font-black uppercase italic tracking-tighter mb-1">{MENU_ITEMS[heroIdx].name}</h3>
                     <p className="text-brand-gold text-[10px] font-bold uppercase tracking-widest">Élu meilleur plat de Niamey</p>
                  </div>
               </div>
            </div>

            {/* MARQUEE PLATS INFINI */}
            <div className="mt-12 overflow-hidden py-4 bg-brand-brown/5">
                <div className="flex animate-marquee whitespace-nowrap gap-6 px-6">
                   {[...items, ...items, ...items].map((item, idx) => (
                     <div key={idx} onClick={() => setSelectedItemForDetails(item)} className="inline-block w-44 h-44 rounded-[2.5rem] overflow-hidden shadow-xl border-4 border-white flex-shrink-0 cursor-pointer active:scale-95 transition-transform">
                        <img src={item.image} className="w-full h-full object-cover" />
                     </div>
                   ))}
                </div>
            </div>

            <div className="mt-10 grid grid-cols-2 gap-4 px-6">
                <button onClick={() => setCurrentPage(Page.TRAITEUR)} className="col-span-2 bg-[#1A0F0D] h-32 rounded-[3rem] text-brand-gold flex items-center justify-between px-10 shadow-2xl group relative overflow-hidden active:scale-95 transition-all">
                   <div className="relative z-10 text-left">
                      <h4 className="font-black text-xl italic uppercase tracking-tighter leading-none mb-1">Traiteur</h4>
                      <p className="text-[9px] font-black text-white/50 uppercase tracking-[0.2em]">Prestige & Event</p>
                   </div>
                   <div className="p-4 bg-brand-gold text-brand-brown rounded-2xl relative z-10 shadow-xl group-hover:rotate-12 transition-transform"><Calendar size={28} /></div>
                </button>
                <button onClick={() => setCurrentPage(Page.MENU)} className="bg-brand-brown h-44 rounded-[4rem] text-brand-gold flex flex-col items-center justify-center gap-4 shadow-2xl transition-all active:scale-95 border-b-8 border-black/20 group">
                   <div className="p-4 bg-white/10 rounded-3xl"><ShoppingBag size={34} /></div>
                   <span className="font-black text-[11px] uppercase tracking-widest italic">La Carte</span>
                </button>
                <div className="grid grid-rows-2 gap-4">
                    <button onClick={() => setCurrentPage(Page.BOX)} className="bg-brand-orange rounded-[3rem] text-white flex items-center justify-center gap-4 font-black text-[10px] uppercase tracking-widest italic shadow-xl active:scale-95 transition-all">
                      <Package size={20} /> Box
                    </button>
                    <button onClick={() => setCurrentPage(Page.PACKS)} className="bg-brand-gold rounded-[3rem] text-brand-brown flex items-center justify-center gap-4 font-black text-[10px] uppercase tracking-widest italic shadow-xl active:scale-95 transition-all">
                      <Trophy size={20} /> Packs
                    </button>
                </div>
            </div>

            {/* SECTION AVIS FANS ALIGNÉS */}
            <div className="mt-16 px-6">
               <div className="flex justify-between items-end mb-8">
                  <div>
                    <h3 className="text-2xl font-black text-brand-brown uppercase italic tracking-tighter leading-none mb-1">Avis Fans</h3>
                    <p className="text-[9px] font-black text-brand-orange uppercase tracking-[0.3em]">Ils nous font confiance</p>
                  </div>
                  <button className="text-[9px] font-black uppercase text-brand-brown underline underline-offset-4 decoration-brand-orange active:text-brand-orange">Ajouter un avis</button>
               </div>

               <div className="grid grid-cols-1 gap-4">
                  {reviews.slice(0, 3).map(rev => (
                    <div key={rev.id} className="bg-white p-6 rounded-[2.5rem] shadow-xl border border-brand-brown/5 flex gap-5 items-start animate-fade-in">
                       <img src={rev.image} className="w-12 h-12 rounded-full object-cover border-2 border-brand-gold shadow-md" />
                       <div className="flex-1">
                          <div className="flex justify-between mb-1">
                             <p className="text-[9px] font-black uppercase tracking-widest">{rev.name}</p>
                             <div className="flex gap-0.5 text-brand-gold">
                                {[...Array(5)].map((_, i) => <Star key={i} size={8} fill={i < rev.rating ? "currentColor" : "none"} />)}
                             </div>
                          </div>
                          <p className="text-[11px] font-bold text-brand-brown/70 italic leading-relaxed">"{rev.comment}"</p>
                       </div>
                    </div>
                  ))}
               </div>
            </div>

            <div className="px-6 mt-12 mb-12"><DeliveryEstimator /></div>
          </div>
        );

      case Page.COMMANDES:
        return (
          <div className="pb-32 animate-fade-in px-6">
             <div className="py-10 text-brand-brown font-black uppercase italic text-3xl tracking-tighter">Mon Suivi</div>
             {activeOrder ? (
               <div className="space-y-6">
                  <OrderTracking order={activeOrder} onComplete={() => setShowReceipt(true)} />
                  <button onClick={() => setShowReceipt(true)} className="w-full bg-brand-brown text-brand-gold py-5 rounded-[2rem] font-black uppercase text-xs shadow-xl flex items-center justify-center gap-2 italic">
                    Ticket de caisse <ChevronRight size={16}/>
                  </button>
               </div>
             ) : (
               <div className="text-center py-20 opacity-20 italic font-black uppercase text-xl">Aucun colis en route</div>
             )}
          </div>
        );

      case Page.COMPTE:
        return (
          <div className="pb-32 animate-fade-in px-6 py-12 flex flex-col items-center">
             <div className="w-40 h-40 rounded-[4rem] bg-brand-brown p-1 border-4 border-white shadow-2xl overflow-hidden relative mb-8 group">
                {profile.photo ? <img src={profile.photo} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center"><User size={64} className="text-white/10" /></div>}
                <button onClick={() => fileInputRef.current?.click()} className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity text-white"><Camera size={32}/></button>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
                  const file = e.target.files?.[0];
                  if(file) {
                    const r = new FileReader();
                    r.onloadend = () => setProfile({...profile, photo: r.result as string});
                    r.readAsDataURL(file);
                  }
                }} />
             </div>
             <h2 className="text-3xl font-black text-brand-brown italic uppercase mb-2 tracking-tighter">{profile.name}</h2>
             <p className="text-[10px] font-black text-brand-orange uppercase tracking-[0.3em] mb-12">Membre Khady Gold ✨</p>

             <div className="w-full space-y-4">
                <div className="bg-white p-6 rounded-[2rem] border border-gray-100 flex items-center justify-between shadow-md">
                   <div className="flex items-center gap-4">
                      <div className="p-3 bg-brand-orange/10 text-brand-orange rounded-xl"><Trophy size={20}/></div>
                      <span className="text-xs font-black uppercase">Points Fidélité</span>
                   </div>
                   <span className="text-sm font-black text-brand-brown italic">1,250 PTS</span>
                </div>

                {/* ACCÈS ADMIN INVISIBLE : SE CONFOND DANS LES PARAMÈTRES */}
                <button onClick={() => {
                  const p = prompt("Code d'accès Admin :");
                  if(p === 'khadysfood') setCurrentPage(Page.ADMIN);
                }} className="w-full p-6 text-gray-300 flex items-center justify-between opacity-30 hover:opacity-100 transition-opacity">
                   <div className="flex items-center gap-4">
                      <Settings size={16} />
                      <span className="text-[10px] font-black uppercase tracking-widest">Réglages Système</span>
                   </div>
                </button>
             </div>
          </div>
        );

      case Page.CART:
        return (
          <div className="pb-32 animate-fade-in px-6 flex flex-col min-h-[80vh]">
             <div className="flex items-center justify-between py-10 text-brand-brown font-black uppercase italic text-3xl tracking-tighter">Mon Panier</div>
             {cart.length === 0 ? (
               <div className="flex-1 flex flex-col items-center justify-center italic opacity-20 font-black uppercase text-xl">Panier Vide</div>
             ) : (
               <div className="space-y-4">
                  {cart.map(item => (
                    <div key={item.id} className="bg-white p-5 rounded-[2.5rem] shadow-xl flex items-center gap-4 border border-brand-brown/5 animate-slide-up">
                       <img src={item.image} className="w-16 h-16 rounded-xl object-cover" />
                       <div className="flex-1">
                          <h4 className="font-black text-[10px] uppercase text-brand-brown">{item.name}</h4>
                          <p className="text-[10px] font-bold text-gray-400">x{item.quantity} • {item.price * item.quantity} F</p>
                       </div>
                    </div>
                  ))}
                  <button onClick={() => setShowUpsell(true)} className="w-full bg-brand-brown text-brand-gold py-6 rounded-[2.5rem] font-black uppercase mt-10 shadow-2xl italic tracking-widest active:scale-95 transition-all">Suivant</button>
               </div>
             )}
          </div>
        );

      case Page.MENU:
      case Page.BOX:
      case Page.PACKS:
        return (
          <div className="pb-32 animate-fade-in px-6">
            <div className="flex items-center justify-between py-10">
               <button onClick={() => setCurrentPage(Page.HOME)} className="p-4 bg-white rounded-2xl shadow-xl text-brand-brown active:scale-90 transition-transform"><ArrowLeft size={20}/></button>
               <h2 className="text-2xl font-black uppercase italic tracking-tighter text-brand-brown">La Carte</h2>
               <div className="w-12 h-12"></div>
            </div>
            <div className="grid grid-cols-2 gap-5">
               {filteredItems.map(item => (
                 <div key={item.id} onClick={() => setSelectedItemForDetails(item)} className="bg-white rounded-[2.5rem] overflow-hidden shadow-xl border border-brand-brown/5 active:scale-95 transition-all group cursor-pointer">
                    <img src={item.image} className="w-full aspect-square object-cover" />
                    <div className="p-5 text-center">
                       <h4 className="font-black text-[10px] uppercase text-brand-brown truncate mb-1">{item.name}</h4>
                       <span className="text-xs font-black text-brand-orange italic">{item.price} F</span>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        );

      case Page.TRAITEUR: return <TraiteurView />;
      default: return null;
    }
  };

  if (showSplash) {
    return (
      <div className={`fixed inset-0 z-[100] bg-black flex items-center justify-center transition-opacity duration-1000 ${splashFade ? 'opacity-0' : 'opacity-100'}`}>
        <video autoPlay muted playsInline className="w-full h-full object-cover" onEnded={closeSplash} onError={closeSplash}>
          <source src={LOGO_VIDEO_URL} type="video/mp4" />
        </video>
        <button onClick={closeSplash} className="absolute bottom-10 right-6 bg-white/20 backdrop-blur-md text-white px-6 py-3 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-2 border border-white/20">Passer <SkipForward size={14} /></button>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-brand-cream/10 shadow-2xl overflow-hidden relative font-sans flex flex-col items-center">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <div className="flex-1 overflow-y-auto no-scrollbar w-full max-w-lg bg-brand-cream/10 min-h-screen relative">{renderContent()}</div>
      <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.length} />
      <AIChat />
      <ItemDetailsModal item={selectedItemForDetails} isOpen={!!selectedItemForDetails} onClose={() => setSelectedItemForDetails(null)} onAddToCart={handleAddToCart} />
      {/* Fix type mismatch: UpsellModal's onAdd only provides 1 argument (the item). We wrap handleAddToCart to provide default quantity (1) and instructions (''). */}
      <UpsellModal isOpen={showUpsell} onClose={() => setShowUpsell(false)} suggestions={items.filter(i => i.category === 'Boisson').slice(0, 3)} onAdd={(item) => handleAddToCart(item, 1, '')} onProceed={handleCheckout} />
      {showReceipt && activeOrder && <Receipt order={activeOrder} onClose={() => setShowReceipt(false)} />}
    </div>
  );
};

export default App;
